const $=id=>document.getElementById(id);const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(Number(n||0));const date=s=>s?new Intl.DateTimeFormat('en-US',{dateStyle:'medium'}).format(new Date(s)):'—';function notice(text,ok=true){$('notice').innerHTML=`<div class="notice ${ok?'ok':'bad'}">${esc(text)}</div>`}function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function load(){try{const r=await fetch('/api/dashboard');const d=await r.json();if(!r.ok)throw Error(d.error);const s=d.summary||{};$('needed').textContent=fmt(s.hoursNeeded);$('filled').textContent=fmt(s.hoursFilled);$('remaining').textContent=fmt(s.hoursRemaining);$('events').textContent=fmt(s.activeEvents);$('rate').textContent=`${Math.round(s.fillRate||0)}% fill rate`;$('open').textContent=`${s.openSlots||0} open slots`;$('assigned').textContent=`${s.assignedSlots||0} assigned slots`;$('last').textContent=date(s.lastSyncAt);const p=d.programs||[];$('programs').innerHTML=p.length?p.map(x=>`<div class="row"><strong>${esc(x.name)}</strong><span>${fmt(x.needed)}</span><span>${fmt(x.filled)}</span><span>${fmt(x.remaining)}</span><div><div class="bar"><i style="width:${Math.min(100,Math.max(0,x.fillRate||0))}%"></i></div><small>${Math.round(x.fillRate||0)}%</small></div></div>`).join(''):'<div class="empty">No program data yet.</div>';const e=d.events||[];$('eventList').innerHTML=e.length?e.map(x=>`<div class="event"><strong>${esc(x.title)}</strong><small>${date(x.eventDate)} · ${esc(x.location||'Location not set')}</small><div class="nums"><span>${fmt(x.hoursFilled)} filled</span><span>${fmt(x.hoursNeeded)} needed</span><span>${x.openSlots||0} open</span></div><div class="bar"><i style="width:${x.hoursNeeded?Math.min(100,x.hoursFilled/x.hoursNeeded*100):0}%"></i></div></div>`).join(''):'<div class="empty">No active events have been synchronized.</div>';const current=$('diagEvent').value;$('diagEvent').innerHTML=e.length?e.map(x=>`<option value="${esc(x.signupgeniusId)}">${esc(x.title)}</option>`).join(''):'<option value="">No active events</option>';if(current&&e.some(x=>String(x.signupgeniusId)===current))$('diagEvent').value=current}catch(e){notice(e.message||'Unable to load dashboard',false)}}
$('sync').onclick=async()=>{const b=$('sync');b.disabled=true;b.textContent='Syncing…';try{const r=await fetch('/api/sync',{method:'POST'});const d=await r.json();if(!r.ok)throw Error(d.error);notice(d.message,true);await load()}catch(e){notice(e.message||'Sync failed',false)}finally{b.disabled=false;b.textContent='Sync SignUpGenius'}};
$('inspect').onclick=async()=>{const eventId=$('diagEvent').value,b=$('inspect');if(!eventId)return;notice('');b.disabled=true;b.textContent='Inspecting…';$('diagnosticResult').innerHTML='<div class="empty">Reading live SignUpGenius reports…</div>';try{const[r1,r2]=await Promise.all([fetch(`/api/diagnostics/report?eventId=${encodeURIComponent(eventId)}`),fetch('/api/diagnostics/accounting')]);const[d1,d2]=await Promise.all([r1.json(),r2.json()]);if(!r1.ok)throw Error(d1.error);if(!r2.ok)throw Error(d2.error);renderAccounting(d2);renderDiagnostic(d1)}catch(e){$('diagnosticResult').innerHTML='';notice(e.message||'Diagnostic request failed',false)}finally{b.disabled=false;b.textContent='Inspect Event Data'}};
function renderAccounting(a){$('accounting').innerHTML=`<div class="accounting"><span><b>${fmt(a.total)}</b> D1 rows</span><span><b>${fmt(a.distinctIds)}</b> unique slot IDs</span><span><b>${fmt(a.zeroHourRows)}</b> zero-hour rows</span>${(a.byStatus||[]).map(x=>`<span><b>${fmt(x.count)}</b> ${esc(x.status)}</span>`).join('')}</div>`}
function renderDiagnostic(d){const root=$('diagnosticResult');root.innerHTML='';const reports=d.reports||{};const cards=document.createElement('div');cards.className='reportcards';for(const[name,r]of Object.entries(reports)){const c=document.createElement('div');c.className='reportcard';c.innerHTML=`<small>${esc(name.toUpperCase())} REPORT</small><strong>${fmt(r.recordCount)} records</strong><span>${fmt((r.detectedPaths||[]).length)} detected field paths</span>`;cards.appendChild(c)}root.appendChild(cards);const n=document.createElement('div');n.className='diagnote';n.textContent='This diagnostic intentionally shows the API’s original JSON so we can identify the exact date/time/duration/quantity and volunteer fields before changing hour calculations.';root.appendChild(n);for(const[name,r]of Object.entries(reports)){const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent=`${name.toUpperCase()} — fields and raw JSON`;details.appendChild(summary);const h1=document.createElement('h3');h1.textContent='Detected field paths';details.appendChild(h1);const paths=document.createElement('div');paths.className='paths';for(const x of r.detectedPaths||[]){const code=document.createElement('code');const left=document.createTextNode(x.path+' ');const em=document.createElement('em');em.textContent=x.type;code.appendChild(left);code.appendChild(em);paths.appendChild(code)}details.appendChild(paths);const h2=document.createElement('h3');h2.textContent='Complete raw response';details.appendChild(h2);const pre=document.createElement('pre');pre.textContent=JSON.stringify(r.raw,null,2);details.appendChild(pre);root.appendChild(details)}}load();
